/**
 * @name Potential path traversal in zip file handling
 * @description Using zip member names in path operations without validation can lead to path traversal
 * @kind path-problem
 * @problem.severity error
 * @id py/zip-path-traversal-flow
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module ZipPathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    exists(DataFlow::AttrRead attr |
      source.asExpr() = attr.asExpr() and
      (
        attr.getAttributeName() = "filename" or
        attr.getAttributeName() = "name"
      )
    )
  }

  predicate isSink(DataFlow::Node sink) {
    exists(API::CallNode call |
      call = API::moduleImport("posixpath").getMember("join").getACall() and
      sink = call.getArg(_)
    )
  }
}

module ZipPathTraversalFlow = TaintTracking::Global<ZipPathTraversalConfig>;
import ZipPathTraversalFlow::PathGraph

from ZipPathTraversalFlow::PathNode source, ZipPathTraversalFlow::PathNode sink
where ZipPathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential path traversal via zip member name from $@.", source.getNode(), "zip member"
